// <diletta-input> — a INSTÂNCIA WEB de `design-system-input`.
//
// O eixo `Estado` (`repouso` · `erro` · `desabilitado`) foi DECLARADO na spec em
// 06/09: ele nasce de campos booleanos e de texto, e o contrato só deriva eixo de
// `enum` — ficou invisível para a lei durante todo o tempo em que o render já o
// pintava.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-input';
const TYPE = ['text', 'password', 'long'];
const ESTADO = ['repouso', 'erro', 'desabilitado'];

let sequencia = 0;

class DilettaInput extends HTMLElement {
  static observedAttributes = ['type', 'estado', 'label', 'valor', 'erro', 'placeholder'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.id_ = `di-${++sequencia}`;
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  /// `erro` com texto IMPLICA `estado: erro`. Deixar os dois soltos permitiria um
  /// campo com mensagem de erro pintado como repouso — que é a peça dizendo duas
  /// coisas ao mesmo tempo.
  get estadoEfetivo() {
    if (this.getAttribute('estado') === 'desabilitado') return 'desabilitado';
    return this.getAttribute('erro') ? 'erro' : eixo(this, 'estado', ESTADO, 'repouso');
  }

  render() {
    const type = eixo(this, 'type', TYPE, 'text');
    const estado = this.estadoEfetivo;
    const p = papeisDe(SLUG, { Type: type, Estado: estado });
    const label = this.getAttribute('label') || '';
    const erro = this.getAttribute('erro') || '';
    const off = estado === 'desabilitado';
    const campo = type === 'long' ? 'textarea' : 'input';

    // 3.3.1/3.3.2: a mensagem de erro é AMARRADA ao campo por
    // `aria-describedby`, não só posta embaixo. Sem o laço, quem usa leitor de
    // tela ouve o campo e não ouve por que ele falhou.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        label { display: block; margin-bottom: 4px; color: var(--cps-textSecondary);
                font-size: var(--cps-type-caption-size, 12px); }
        .caixa {
          /* A borda vem da PINTURA e não de constante: a tabela medida dá um
             papel por estado, e o erro tem o dele. A versão anterior escrevia um
             atalho fixo DEPOIS da pintura, e a borda vermelha do erro nunca
             aparecia — o teste passava porque lia o texto do CSS, e só a cascata
             decidia. (Sem crase: isto mora num template literal.) */
          border-width: 1px; border-style: solid; border-color: transparent;
          ${estiloDa(p)}
          box-sizing: border-box; width: 100%;
          border-radius: 8px; padding: 12px;
          font: inherit; color: var(--cps-fg);
          min-height: ${type === 'long' ? '96px' : '48px'};
        }
        .caixa:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 1px; }
        .erro { margin-top: 4px; color: var(--cps-error);
                font-size: var(--cps-type-caption-size, 12px); }
      </style>
      ${label ? `<label for="${this.id_}">${label}</label>` : ''}
      <${campo} id="${this.id_}" class="caixa"
        ${type === 'long' ? '' : `type="${type === 'password' ? 'password' : 'text'}"`}
        ${off ? 'disabled' : ''}
        ${erro ? `aria-invalid="true" aria-describedby="${this.id_}-erro"` : ''}
        placeholder="${(this.getAttribute('placeholder') || '').replace(/"/g, '&quot;')}"
        >${type === 'long' ? (this.getAttribute('valor') || '') : ''}</${campo}>
      ${erro ? `<p class="erro" id="${this.id_}-erro">${erro}</p>` : ''}`;
  }
}

customElements.define('diletta-input', DilettaInput);
export { DilettaInput };
